import Link from "next/link";

/**
 * The product mark: a red tile carrying a white "IP" monogram with a folded
 * page corner — the same geometry the shipped application uses for
 * IrfanPDF.ico / the sidebar logo (generated by tools/make_icon.py),
 * redrawn here as original inline SVG. No external assets, no CDN.
 */
export function Logo({
  withWordmark = true,
  className = "",
}: {
  withWordmark?: boolean;
  className?: string;
}) {
  return (
    <span className={`inline-flex items-center gap-2.5 ${className}`}>
      <svg
        viewBox="0 0 64 64"
        role="img"
        aria-label="Irfan PDF logo"
        className="h-9 w-9 shrink-0"
      >
        <defs>
          <linearGradient id="ipdfTile" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="#FF0000" />
            <stop offset="100%" stopColor="#CC0000" />
          </linearGradient>
        </defs>
        <rect x="4" y="4" width="56" height="56" rx="12" fill="url(#ipdfTile)" />
        {/* folded page corner */}
        <path d="M44 4 L60 20 L48 20 C45.8 20 44 18.2 44 16 Z" fill="#ffffff" opacity="0.92" />
        <path d="M44 4 L44 16 C44 18.2 45.8 20 48 20 L60 20 Z" fill="#ffd7d7" opacity="0.9" />
        {/* IP monogram */}
        <rect x="14" y="24" width="6.4" height="24" rx="2" fill="#ffffff" />
        <path
          d="M26 24 h8.5 c6.6 0 11 4 11 10.4 0 6.5-4.5 10.5-11.2 10.5 H26 Z M32.4 30 v9.4 h2.2 c3.2 0 5.2-1.7 5.2-4.8 0-3-1.9-4.6-5-4.6 Z"
          fill="#ffffff"
        />
      </svg>
      {withWordmark && (
        <span className="text-lg font-extrabold tracking-tight">
          Irfan <span className="text-brand dark:text-[#ff6b6b]">PDF</span>
        </span>
      )}
    </span>
  );
}

export function LogoLink() {
  return (
    <Link
      href="/"
      aria-label="Irfan PDF home"
      className="rounded-lg px-1 py-1 transition-opacity hover:opacity-80"
    >
      <Logo />
    </Link>
  );
}
